<?php require_once __DIR__.'/config.php';$orders=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$number=strtoupper(trim($_POST['order_number']??''));$wa=preg_replace('/\D/','',$_POST['whatsapp']??'');$st=db()->prepare('SELECT o.* FROM orders o JOIN customers c ON c.id=o.customer_id WHERE o.order_number=? AND c.whatsapp=?');$st->execute([$number,$wa]);$orders=$st->fetchAll();$searched=true;}$title='Track Order';require __DIR__.'/includes/header.php';?><main class="track-wrap"><div class="eyebrow">MY ORDERS</div><h1 class="serif text-5xl">Track your order.</h1><form method="post" class="bg-white p-7 mt-7"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="two-col"><div class="field"><label>Nomor pesanan</label><input required name="order_number" placeholder="J001"></div><div class="field"><label>Nomor WhatsApp</label><input required name="whatsapp" placeholder="628..."></div></div><button class="btn gold">TRACK ORDER</button></form><?php if(isset($searched)&&!$orders):?><p class="error mt-4">Pesanan tidak ditemukan. Periksa nomor pesanan dan WhatsApp Anda.</p><?php endif;?><?php foreach($orders as $o):?><article class="bg-white p-7 mt-5"><div class="flex justify-between"><div><div class="eyebrow">ORDER NUMBER</div><h2 class="serif text-3xl m-0"><?=e($o['order_number'])?></h2></div><strong><?=money((float)$o['total'])?></strong></div><div class="grid md:grid-cols-2 gap-4 mt-5 text-sm"><p>Payment: <span class="status"><?=e(str_replace('_',' ', $o['payment_status']))?></span></p><p>Production: <span class="status"><?=e(str_replace('_',' ', $o['production_status']))?></span></p></div><div class="mt-5 flex justify-between text-xs text-slate-500 border-t pt-4"><span>1. Order Created</span><span>2. Payment</span><span>3. Processing</span><span>4. Completed</span></div><?php if($o['payment_status']==='waiting_payment'):?><a class="btn gold mt-5" href="<?=url('payment-proof.php?order='.$o['order_number'])?>">UPLOAD PAYMENT PROOF</a><?php endif;?></article><?php endforeach;?></main><?php require __DIR__.'/includes/footer.php'; ?>
